async function getUserProfile(userId: string): Promise<UserProfile | null> {
  const cacheKey = `user:profile:v1:${userId}`;
  const cached = await redis.get(cacheKey);

  if (cached !== null) {
    return cached === '__NULL__' ? null : JSON.parse(cached);
  }

  const user = await db.users.findUnique({ where: { id: userId } });
  if (!user) {
    // Cache sentinel with short 60s TTL to prevent DB penetration attacks
    await redis.set(cacheKey, '__NULL__', 'EX', 60);
    return null;
  }

  // Add randomized jitter (3600s + 0..300s) to avoid mass synchronized expiration
  const ttlSeconds = 3600 + Math.floor(Math.random() * 300);
  await redis.set(cacheKey, JSON.stringify(user), 'EX', ttlSeconds);
  return user;
}

export class WriteThroughCache<T> {
  constructor(private cache: CacheStore, private db: DatabaseStore) {}

  async get(key: string): Promise<T | null> {
    const cached = await this.cache.get(key);
    if (cached) return JSON.parse(cached);

    // Transparently fetch from DB on miss
    const record = await this.db.fetchById(key);
    if (record) {
      await this.cache.set(key, JSON.stringify(record), 3600);
    }
    return record;
  }

  async set(key: string, value: T): Promise<void> {
    // Synchronously write to DB first to ensure durability
    await this.db.persist(key, value);
    // Update in-memory cache before acknowledging client
    await this.cache.set(key, JSON.stringify(value), 3600);
  }
}

// 1. Fast in-memory increment
export async function recordPageView(pageId: string) {
  // Atomic in-memory increment (<1ms)
  await redis.hincrby("page_views_buffer", pageId, 1);
}

// 2. Scheduled background worker flushes batched increments every 10 seconds
export async function flushPageViewsToDatabase(db: DatabaseClient) {
  const snapshot = await redis.hgetall("page_views_buffer");
  if (!snapshot || Object.keys(snapshot).length === 0) return;

  // Atomically swap or delete flushed keys
  await redis.del("page_views_buffer");

  const entries = Object.entries(snapshot);
  // Batch UPSERT into relational database
  const sql = `
    INSERT INTO page_metrics (page_id, view_count)
    VALUES ${entries.map(([id, cnt]) => `('${id}', ${cnt})`).join(",")}
    ON CONFLICT (page_id)
    DO UPDATE SET view_count = page_metrics.view_count + EXCLUDED.view_count;
  `;
  await db.query(sql);
}

export function calculateJitteredTtl(
  baseTtlSeconds: number,
  maxJitterSeconds = 300
): number {
  // Add a uniform random offset (e.g., 3600s + 0..300s)
  const jitter = Math.floor(Math.random() * maxJitterSeconds);
  return baseTtlSeconds + jitter;
}

