class DListNode {
  constructor(public key: string, public value: any, public prev: DListNode | null = null, public next: DListNode | null = null) {}
}

export class LRUCache {
  private map = new Map<string, DListNode>();
  private head: DListNode = new DListNode("", null);
  private tail: DListNode = new DListNode("", null);

  constructor(private capacity: number) {
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key: string): any {
    const node = this.map.get(key);
    if (!node) return null;
    this.moveToHead(node); // Promoted to MRU
    return node.value;
  }

  private moveToHead(node: DListNode) {
    // Detach
    node.prev!.next = node.next;
    node.next!.prev = node.prev;
    // Attach behind head
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next!.prev = node;
    this.head.next = node;
  }
}

interface WalChangeEvent {
  table: string;
  op: 'INSERT' | 'UPDATE' | 'DELETE';
  before: Record<string, any>;
  after: Record<string, any>;
}

export async function handleCdcInvalidationEvent(event: WalChangeEvent) {
  const { table, op, after, before } = event;

  if (table === 'users') {
    const userId = after?.id || before?.id;
    // Invalidate primary user entity cache
    await redis.del(`user:profile:v1:${userId}`);
    // Invalidate composite user membership cache
    await redis.del(`user:teams:v1:${userId}`);
  }
}

class Singleflight {
  private inFlight = new Map<string, Promise<any>>();

  async do<T>(key: string, fn: () => Promise<T>): Promise<T> {
    // If a request for this key is already running, return the active promise
    const active = this.inFlight.get(key);
    if (active) return active as Promise<T>;

    const promise = (async () => {
      try {
        return await fn();
      } finally {
        this.inFlight.delete(key);
      }
    })();

    this.inFlight.set(key, promise);
    return promise;
  }
}

const group = new Singleflight();
export async function getDashboardData(userId: string) {
  return group.do(`dashboard:${userId}`, async () => {
    // Only 1 execution touches the DB per instance!
    return db.fetchExpensiveDashboard(userId);
  });
}

const SHARD_COUNT = 16;

// Read: Pick a random salt to distribute reads across 16 different Redis nodes
export async function getCelebrityFeed(celebrityId: string): Promise<FeedData> {
  const randomSalt = Math.floor(Math.random() * SHARD_COUNT);
  const saltedKey = `feed:${celebrityId}#${randomSalt}`;
  const cached = await redis.get(saltedKey);
  return cached ? JSON.parse(cached) : fetchFromDbAndPopulate(celebrityId);
}

// Write: Must write/invalidate all 16 salted keys concurrently
export async function updateCelebrityFeed(celebrityId: string, feedData: FeedData): Promise<void> {
  const pipeline = redis.pipeline();
  for (let i = 0; i < SHARD_COUNT; i++) {
    pipeline.set(`feed:${celebrityId}#${i}`, JSON.stringify(feedData), 'EX', 3600);
  }
  await pipeline.exec();
}

export async function checkRateLimit(
  userId: string,
  limit = 100,
  windowMs = 60000
): Promise<boolean> {
  const key = `ratelimit:${userId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  // Pipeline multi-step operations to reduce RTT
  const pipeline = redis.pipeline();
  pipeline.zremrangebyscore(key, 0, windowStart); // Drop expired timestamps
  pipeline.zadd(key, now, `${now}-${Math.random()}`); // Add current timestamp
  pipeline.zcard(key); // Count requests in active window
  pipeline.pexpire(key, windowMs); // Reset TTL

  const results = await pipeline.exec();
  const requestCount = results![2][1] as number;
  return requestCount <= limit;
}
